export const getRandomMonthExcludingCurrent = (): number => {
  const currentMonth = new Date().getMonth();

  let randomMonth;
  do {
    randomMonth = Math.floor(Math.random() * 12);
  } while (randomMonth === currentMonth);

  return randomMonth;
};

